SELECT 
  FROM RAW_ENV_TB
 WHERE RAW_SEQ = #{rawSeq}
   AND DEL_YN = 0

   AND MET_KEY = #{metKey}

 ORDER BY MET_KEY, ROW_NO

SELECT IFNULL(MAX(ROW_NO), 0) + 1
  FROM RAW_ENV_TB
 WHERE RAW_SEQ = #{rawSeq}
   AND MET_KEY = #{metKey}

SELECT REV_YN
  FROM MEMBER_TB
 WHERE ID = #{memId}
